mapper.select:
SELECT

FROM mes_quality_record


        AND id = #{query.id}


        AND task_id IN (SELECT id FROM mes_quality_task WHERE task_no LIKE CONCAT('%', #{query.taskNo}, '%'))


        AND plan_id IN (SELECT id FROM mes_quality_plan WHERE plan_no LIKE CONCAT('%', #{query.planNo}, '%'))


        AND task_id IN (SELECT id FROM mes_quality_task WHERE product_code = #{query.productCode})


        AND task_id IN (SELECT id FROM mes_quality_task WHERE batch_no = #{query.batchNo})


        AND item_code = #{query.itemCode}


        AND item_name LIKE CONCAT('%', #{query.itemName}, '%')


        AND task_id IN (SELECT id FROM mes_quality_task WHERE inspector = #{query.inspector})


        AND result = #{query.result}


        AND defect_code = #{query.defectCode}


        AND create_time >= #{query.inspectionTimeStart}


        AND create_time <= #{query.inspectionTimeEnd}


        AND item_id IN (SELECT id FROM mes_inspection_item WHERE data_type = #{query.dataType})


        AND item_id IN (SELECT id FROM mes_inspection_item WHERE is_critical = #{query.isCritical})


ORDER BY create_time DESC

SELECT

FROM mes_quality_record

    actual_value IS NOT NULL

        AND item_id = #{query.itemId}


        AND item_code = #{query.itemCode}


        AND task_id IN (
        SELECT id FROM mes_quality_task
        WHERE product_code = #{query.productCode}
        )


        AND DATE(create_time) >= #{query.startDate}


        AND DATE(create_time) <= #{query.endDate}


ORDER BY create_time ASC

SELECT

FROM mes_quality_record
WHERE item_id = #{itemId}
AND DATE(create_time) BETWEEN #{startDate} AND #{endDate}
AND actual_value IS NOT NULL
ORDER BY create_time ASC
